double elapsedMs(const QElapsedTimer& timer) {
    return timer.nsecsElapsed() / 1000000.0;
}

QString environmentOr(const char* name, const QString& fallback) {
    const auto value = qEnvironmentVariable(name);
    return value.isEmpty() ? fallback : value;
}

QJsonObject failedTrack(const QString& id,
        const QString& digest,
        const QString& message) {
    return {{"id", id},
            {"audio_sha256", digest},
            {"status", "error"},
            {"error", message}};
}

// This exporter can also be compiled beside the pre-worker baseline. Missing
// stage instrumentation stays unavailable instead of becoming invented zeros.
template<typename Analyzer>
QJsonObject timingMetrics(const Analyzer& analyzer) {
    if constexpr (requires { analyzer.lastTimingMetrics(); }) {
        return analyzer.lastTimingMetrics();
    }
    return {};
}

template<typename Analyzer>
QJsonObject analysisDiagnostics(const Analyzer& analyzer) {
    if constexpr (requires { analyzer.analysisDiagnostics(); }) {
        return analyzer.analysisDiagnostics();
    }
    return {};
}

template<typename Grid>
void appendDownbeatsIfSupported(QJsonObject* result,
        const Grid& grid,
        mixxx::audio::SampleRate rate,
        double duration) {
    if constexpr (requires { grid.getDownbeats(); }) {
        QJsonArray downbeats;
        for (const auto downbeat : grid.getDownbeats()) {
            const double seconds = downbeat.value() / rate;
            if (seconds >= 0 && seconds < duration) {
                downbeats.append(seconds);
            }
        }
        result->insert("downbeats", downbeats);
    }
}

class NativeBeatBenchmarkTest : public MixxxTest,
                                SoundSourceProviderRegistration {
  protected:
    QJsonObject analyze(const QJsonObject& entry, const QDir& base) {
        const auto id = entry.value("id").toString();
        const auto digest = entry.value("audio_sha256").toString().toLower();
        const auto relativePath =
                entry.value("audio_file")
                        .toString(entry.value("audio_path").toString());
        const auto path = base.absoluteFilePath(relativePath);
        QElapsedTimer wall;
        const auto fail = [&](const QString& message) {
            ADD_FAILURE() << id.toStdString() << ": " << message.toStdString();
            auto result = failedTrack(id, digest, message);
            if (wall.isValid()) {
                result.insert("timings_ms", QJsonObject{{"wall", elapsedMs(wall)}});
            }
            return result;
        };
        if (relativePath.isEmpty() ||
                !QRegularExpression(QStringLiteral("^[0-9a-f]{64}$"))
                        .match(digest)
                        .hasMatch()) {
            return fail(QStringLiteral("Missing audio_file/audio_path or SHA-256 identity"));
        }
        QFile audioFile(path);
        if (!audioFile.open(QIODevice::ReadOnly)) {
            return fail(QStringLiteral("Cannot open source audio"));
        }
        QElapsedTimer hashing;
        hashing.start();
        QCryptographicHash hash(QCryptographicHash::Sha256);
        if (!hash.addData(&audioFile) ||
                QString::fromLatin1(hash.result().toHex()) != digest) {
            return fail(QStringLiteral("Source audio SHA-256 mismatch"));
        }
        const double hashMs = elapsedMs(hashing);
        audioFile.close();

        // File identity verification is benchmark bookkeeping. Analysis wall
        // time starts after hashing, and every timing stage is measured.
        wall.start();
        QElapsedTimer phase;
        phase.start();
        auto track = Track::newTemporary(path);
        SoundSourceProxy proxy(track);
        mixxx::AudioSource::OpenParams params;
        params.setChannelCount(mixxx::kAnalysisMaxChannels);
        auto source = proxy.openAudioSource(params);
        if (!source) {
            return fail(QStringLiteral("Mixxx decoder could not open the source"));
        }
        const auto provider = proxy.getProvider();
        const auto providerName = provider ? provider->getDisplayName() : QStringLiteral("unknown");
        const bool stereoProxy =
                source->getSignalInfo().getChannelCount() % mixxx::kAnalysisChannels != 0;
        if (stereoProxy) {
            source = mixxx::AudioSourceStereoProxy::create(
                    source, mixxx::kAnalysisFramesPerChunk);
        }
        double decodeMs = elapsedMs(phase);
        const auto rate = source->getSignalInfo().getSampleRate();
        const auto channels = source->getSignalInfo().getChannelCount();
        const auto frameStart = source->frameIndexMin();
        const auto initialFrames = source->frameLength();
        AnalyzerBeats analyzer(config(), true);
        phase.restart();
        if (!analyzer.initialize(AnalyzerTrack(track), rate, channels, initialFrames)) {
            source->close();
            return fail(QStringLiteral("Beat analyzer initialization failed"));
        }
        const double initializeMs = elapsedMs(phase);
        mixxx::SampleBuffer buffer(mixxx::kAnalysisSamplesPerChunk);
        auto remaining = source->frameIndexRange();
        SINT decodedFrames = 0;
        double processingMs = 0;
        bool processed = true;
        QString decodeError;
        while (!remaining.empty()) {
            auto requested = remaining.splitAndShrinkFront(
                    std::min(mixxx::kAnalysisFramesPerChunk, remaining.length()));
            phase.restart();
            const auto readable = source->readSampleFrames(mixxx::WritableSampleFrames(
                    requested, mixxx::SampleBuffer::WritableSlice(buffer)));
            decodeMs += elapsedMs(phase);
            requested = intersect(requested, source->frameIndexRange());
            remaining = intersect(remaining, source->frameIndexRange());
            if (!readable.frameIndexRange().isSubrangeOf(requested)) {
                decodeError = QStringLiteral("Decoder returned frames outside its requested range");
                break;
            }
            if (remaining.end() != source->frameIndexRange().end() && !remaining.empty()) {
                decodeError = QStringLiteral("Decoder frame range grew unexpectedly");
                break;
            }
            decodedFrames += readable.frameLength();
            if (!readable.frameIndexRange().empty()) {
                phase.restart();
                processed = analyzer.processSamples(
                        readable.readableData(), readable.readableLength());
                processingMs += elapsedMs(phase);
                if (!processed) {
                    break;
                }
            }
        }
        const auto finalFrames = source->frameLength();
        const auto finalFrameStart = source->frameIndexMin();
        const double duration = source->getDuration();
        source->close();
        if (!decodeError.isEmpty() || !processed || decodedFrames == 0) {
            analyzer.cleanup();
            return fail(decodeError.isEmpty()
                            ? QStringLiteral("Decoding or streaming analysis failed")
                            : decodeError);
        }
        phase.restart();
        analyzer.storeResults(track);
        const double finalizeMs = elapsedMs(phase);
        QJsonObject timings = timingMetrics(analyzer);
        const QJsonObject diagnostics = analysisDiagnostics(analyzer);
        analyzer.cleanup();
        const double wallMs = elapsedMs(wall);
        const auto grid = track->getBeats();
        if (!grid) {
            return fail(QStringLiteral("Analysis produced no beat grid"));
        }
        timings.insert("hash_validation", hashMs);
        timings.insert("decode", decodeMs);
        timings.insert("initialize", initializeMs);
        timings.insert("stream_processing", processingMs);
        timings.insert("finalization", finalizeMs);
        timings.insert("wall", wallMs);
        QJsonArray beats;
        for (auto beat = grid->iteratorFrom(mixxx::audio::kStartFramePos);
                (*beat).value() < finalFrames;
                ++beat) {
            const double seconds = (*beat).value() / rate;
            if (seconds >= 0) {
                beats.append(seconds);
            }
            if (beats.size() > 1000000) {
                return fail(QStringLiteral("Grid exceeded export safety limit"));
            }
        }
        QJsonObject result{{"id", id},
                {"audio_sha256", digest},
                {"status", "ok"},
                {"timeline_id",
                        QStringLiteral("mixxx:%1:nativeframes:%2")
                                .arg(providerName)
                                .arg(rate.value())},
                {"beats", beats},
                {"constant", grid->hasConstantTempo()},
                {"timings_ms", timings},
                {"analysis_diagnostics", diagnostics},
                {"decoder",
                        QJsonObject{{"provider", providerName},
                                {"stereo_proxy", stereoProxy},
                                {"sample_rate", static_cast<int>(rate.value())},
                                {"channels",
                                        static_cast<int>(channels.value())},
                                {"initial_frame_start",
                                        static_cast<double>(frameStart)},
                                {"initial_frame_count",
                                        static_cast<double>(initialFrames)},
                                {"frame_start",
                                        static_cast<double>(finalFrameStart)},
                                {"frame_count",
                                        static_cast<double>(finalFrames)},
                                {"frames_read",
                                        static_cast<double>(decodedFrames)},
                                {"duration", duration}}}};
        // Stock Mixxx has no downbeat API. Omission means unavailable;
        // an empty array would incorrectly report that every downbeat was missed.
        appendDownbeatsIfSupported(&result, *grid, rate, duration);
        if (grid->hasConstantTempo()) {
            result.insert("bpm",
                    grid->getBpmInRange(mixxx::audio::kStartFramePos,
                                mixxx::audio::FramePos(finalFrames))
                            .value());
        } else {
            QJsonArray zones;
            for (qsizetype i = 1; i < beats.size(); ++i) {
                const double start = beats[i - 1].toDouble();
                const double end = beats[i].toDouble();
                if (!(end > start)) {
                    return fail(QStringLiteral("Grid has non-increasing beat positions"));
                }
                zones.append(QJsonObject{{"start", start},
                        {"end", end},
                        {"bpm", 60 / (end - start)}});
            }
            result.insert("tempo_zones", zones);
        }
        // Variable beat positions remain the primary tempo representation;
        // exporting a scalar median would conceal its actual tempo changes.
        return result;
    }
};

TEST_F(NativeBeatBenchmarkTest, ExportSelectedManifestThroughTheProductionDecoder) {
    const auto manifestPath = qEnvironmentVariable("MIXXX_TEST_BEAT_BENCHMARK_MANIFEST");
    if (manifestPath.isEmpty()) {
        GTEST_SKIP() << "Set MIXXX_TEST_BEAT_BENCHMARK_MANIFEST for native benchmark export";
    }
    const auto outputPath = qEnvironmentVariable("MIXXX_TEST_BEAT_BENCHMARK_OUTPUT");
    ASSERT_FALSE(outputPath.isEmpty());
    const auto split = environmentOr("MIXXX_TEST_BEAT_BENCHMARK_SPLIT", QStringLiteral("dev"));
    ASSERT_TRUE(split == "dev" || split == "holdout" || split == "all");
    QFile manifestFile(manifestPath);
    ASSERT_TRUE(manifestFile.open(QIODevice::ReadOnly));
    const auto manifest = QJsonDocument::fromJson(manifestFile.readAll());
    ASSERT_TRUE(manifest.isObject());
    ASSERT_EQ(1, manifest.object().value("version").toInt());
    ASSERT_TRUE(manifest.object().value("tracks").isArray());
    const auto plugins = AnalyzerBeats::availablePlugins();
    ASSERT_FALSE(plugins.isEmpty());
    const auto isKnownPlugin = [&plugins](const QString& id) {
        return std::any_of(plugins.cbegin(), plugins.cend(), [&id](const auto& info) {
            return info.id() == id;
        });
    };
    const auto defaultPlugin = isKnownPlugin(QStringLiteral("custom-models:1"))
            ? QStringLiteral("custom-models:1")
            : AnalyzerBeats::defaultPlugin().id();
    const auto plugin = environmentOr("MIXXX_TEST_BEAT_BENCHMARK_PLUGIN", defaultPlugin);
    ASSERT_TRUE(isKnownPlugin(plugin)) << "Unavailable beat plugin: " << plugin.toStdString();
    BeatDetectionSettings settings(config());
    settings.setBeatPluginId(plugin);
    settings.setFastAnalysis(false);
    QJsonObject candidateSettings{{"plugin", plugin},
            {"fast_analysis", false},
            {"split", split},
            {"platform", QSysInfo::prettyProductName()},
            {"architecture", QSysInfo::currentCpuArchitecture()},
            {"timing_scope",
                    "sequential beat analysis; decode and model; no library "
                    "database write"}};
#if MIXXX_BENCHMARK_TEMPO_MODES
    const auto constantPlugin = environmentOr(
            "MIXXX_TEST_BEAT_BENCHMARK_CONSTANT", QStringLiteral("beat-this:1"));
    const auto variablePlugin = environmentOr(
            "MIXXX_TEST_BEAT_BENCHMARK_VARIABLE", QStringLiteral("qm-tempotracker:0"));
    ASSERT_TRUE(isKnownPlugin(constantPlugin) && constantPlugin != "custom-models:1")
            << "Unavailable Constant backend: " << constantPlugin.toStdString();
    ASSERT_TRUE(isKnownPlugin(variablePlugin) && variablePlugin != "custom-models:1")
            << "Unavailable Variable backend: " << variablePlugin.toStdString();
    settings.setCustomConstantPlugin(constantPlugin);
    settings.setCustomVariablePlugin(variablePlugin);
    settings.setTempoMode(mixxx::BeatGridMode::Auto);
    candidateSettings.insert("constant_plugin", constantPlugin);
    candidateSettings.insert("variable_plugin", variablePlugin);
    candidateSettings.insert("tempo_mode", "auto");
    candidateSettings.insert("model_sha256", settings.getBeatThisModelSha256());
    candidateSettings.insert("queen_mary_downbeats", settings.getQueenMaryDownbeats());
    candidateSettings.insert("worker_mode",
            qEnvironmentVariableIntValue("MIXXX_BEAT_THIS_ONESHOT") == 1
                    ? "oneshot"
                    : "persistent");
    const auto python = qEnvironmentVariable("MIXXX_TEST_BEAT_THIS_PYTHON");
    const auto model = qEnvironmentVariable("MIXXX_TEST_BEAT_THIS_MODEL");
    if (!python.isEmpty()) {
        settings.setBeatThisPython(python);
    }
    if (!model.isEmpty()) {
        settings.setBeatThisModel(model);
    }
#else
    ASSERT_TRUE(qEnvironmentVariable("MIXXX_TEST_BEAT_BENCHMARK_CONSTANT").isEmpty());
    ASSERT_TRUE(qEnvironmentVariable("MIXXX_TEST_BEAT_BENCHMARK_VARIABLE").isEmpty());
    settings.setFixedTempoAssumption(true);
    candidateSettings.insert("tempo_mode", "constant");
    candidateSettings.insert("fixed_tempo_assumption", true);
    candidateSettings.insert("routing", "stock single-analyzer; custom models unavailable");
#endif
    QJsonArray results;
    QSet<QString> ids;
    const auto base = QFileInfo(manifestPath).absoluteDir();
    QElapsedTimer run;
    run.start();
    for (const auto& value : manifest.object().value("tracks").toArray()) {
        ASSERT_TRUE(value.isObject());
        const auto entry = value.toObject();
        const auto trackSplit = entry.value("split").toString();
        ASSERT_TRUE(trackSplit == "dev" || trackSplit == "holdout");
        if (split != "all" && split != trackSplit) {
            continue;
        }
        const auto id = entry.value("id").toString();
        ASSERT_FALSE(id.isEmpty());
        ASSERT_FALSE(ids.contains(id));
        ids.insert(id);
        results.append(analyze(entry, base));
    }
    ASSERT_FALSE(results.isEmpty());
    const double runWallMs = elapsedMs(run);
    const QJsonObject output{{"version", 1},
            {"candidate",
                    QJsonObject{
                            {"name",
                                    environmentOr(
                                            "MIXXX_TEST_BEAT_BENCHMARK_NAME",
                                            QStringLiteral("Mixxx native"))},
                            {"version",
                                    environmentOr(
                                            "MIXXX_TEST_BEAT_BENCHMARK_VERSION",
                                            VersionStore::gitDescribe())},
                            {"settings", candidateSettings}}},
            {"run_measurements",
                    QJsonObject{{"wall_ms", runWallMs},
                            {"scope",
                                    "selected sequential tracks including "
                                    "source hashing and analysis; excludes "
                                    "JSON writing and application startup"}}},
            {"tracks", results}};
    QSaveFile outputFile(outputPath);
    ASSERT_TRUE(outputFile.open(QIODevice::WriteOnly));
    const auto data = QJsonDocument(output).toJson();
    ASSERT_EQ(data.size(), outputFile.write(data));
    ASSERT_TRUE(outputFile.commit());
}

